"use server";

// Generated by philote from component ClientPicker's picks. Do not edit.
import { cookies } from "next/headers";
import { redirect } from "next/navigation";

import { viewerCookie } from "@/lib/viewer";

// pick makes a Client the viewer for a year, then opens /book.
export async function pick(id: string): Promise<void> {
    (await cookies()).set(viewerCookie, id, {
        path: "/",
        httpOnly: true,
        sameSite: "lax",
        maxAge: 60 * 60 * 24 * 365,
    });
    redirect("/book");
}
